import { ArrowUpRight, BriefcaseBusiness } from 'lucide-react';
import { experiences } from '@/data/portfolio';
import { AnimatedSection } from '@/components/ui/AnimatedSection';

export function ExperienceSection() { return <section id="experience" className="section-wrap"><AnimatedSection><p className="section-kicker">02 / Experience</p><div className="section-intro"><h2>Production work, measured in systems and outcomes.</h2><p>Experience across cloud platforms, enterprise applications, and observability tooling—with an emphasis on making operational complexity easier to reason about.</p></div></AnimatedSection><div className="timeline">{experiences.map((item, index) => <AnimatedSection className="timeline-item" key={item.company}><div className="timeline-marker"><span>{String(index + 1).padStart(2, '0')}</span></div><article className="experience-card"><div className="experience-top"><div><p className="eyebrow">{item.dates}</p><h3>{item.company}</h3><p className="role">{item.role} <span>·</span> {item.location || 'United States'}</p></div><BriefcaseBusiness className="muted-icon" size={22} /></div><p className="impact-line">{item.impact}</p><p className="focus-line">Focus · {item.focus}</p><ul>{item.accomplishments.map((line) => <li key={line}>{line}</li>)}</ul><div className="tag-row">{item.technologies.map((tag) => <span className="tag" key={tag}>{tag}</span>)}</div></article></AnimatedSection>)}</div></section>; }
